// app/shared-metadata.ts
export const openGraph = {
  siteName: "Trailhead",
  type: "website",
} as const;

// app/layout.tsx, inside the root layout
export const metadata: Metadata = {
  metadataBase: new URL("https://trailhead.example"),
  title: {
    template: "%s | Trailhead",
    default: "Trailhead",
  },
  description: "Packs, tents, and camp gear for long days outside.",
  openGraph,
};

// app/products/[slug]/page.tsx, next to the page
export async function generateMetadata({ params }: PageProps<"/products/[slug]">): Promise<Metadata> {
  const { slug } = await params;
  const product = await getProduct(slug);
  if (!product) notFound();

  return {
    title: product.name,
    description: product.description,
    alternates: { canonical: `/products/${slug}` },
    openGraph: { ...openGraph, title: product.name, url: `/products/${slug}` },
  };
}

import { notFound } from "next/navigation";
import { ImageResponse } from "next/og";
import { getProduct, listProducts } from "@/lib/products";

export const alt = "A Trailhead product";
export const size = { width: 1200, height: 630 };
export const contentType = "image/png";

export async function generateStaticParams() {
  const products = await listProducts();
  return products.map((p) => ({ slug: p.slug }));
}

export default async function Image({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const product = await getProduct(slug);
  if (!product) notFound();
  const price = "$" + (product.priceCents / 100).toFixed(2);

  return new ImageResponse(
    (
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          padding: 80,
          background: "#1f3d2c",
          color: "#f2efe6",
        }}
      >
        <div style={{ fontSize: 40 }}>Trailhead</div>
        <div style={{ fontSize: 96 }}>{product.name}</div>
        <div style={{ fontSize: 48 }}>{price}</div>
      </div>
    ),
    size,
  );
}

steps.body:
A web font is a file the browser has to download before it can draw text in that font. Until it arrives, the browser shows the text in a fallback font, or shows nothing. When the real font lands and it's a different size from the fallback, every line moves, which is the jump the web course called a flash of unstyled text and a layout shift. Fonts from a font service also mean another connection to another company on every visit. `next/font` solves both.

## Google fonts, served from your own site

```tsx sketch
import { Geist } from "next/font/google";

const geistSans = Geist({
  variable: "--font-geist-sans",
  subsets: ["latin"],
});
```

That's how create-next-app sets up its Geist font in `app/layout.tsx`. It looks like a call to Google, but the work happens at build time: Next.js downloads the font files and their CSS once, saves them in `.next/static/media`, and serves them from your own site. The visitor's browser never contacts Google, so there's no extra connection and nothing about the visitor goes to a third party. The files get content-hashed names, and the first example shows they're served with `Cache-Control: public, max-age=31536000, immutable`, a year with no need to check, like the hashed bundles from the web course.

`subsets: ["latin"]` says which characters you need. The font comes split into several files, each covering one **Unicode range**, a block of characters like Latin, Cyrillic, or Vietnamese. The built CSS had five `@font-face` rules for Geist, one per range. Only the Latin file is **preloaded**, named in a `Link` header so the browser fetches it before it reads the CSS. The others download only if a page actually uses those characters.

Geist is a **variable font**: one file holds every weight from 100 to 900, which the built CSS states as `font-weight: 100 900`. One file instead of one per weight is why the docs recommend variable fonts.

## A fallback with the same shape

Next.js also writes a second font face, `Geist Fallback`, built on Arial, which every computer has. It's adjusted with `size-adjust`, `ascent-override`, and `descent-override`, CSS properties that stretch Arial to take up the same width and height as Geist. Until Geist arrives, text shows in this adjusted Arial, and when Geist swaps in, the words stay where they were. The swap itself is `font-display: swap`, the default. The second example shows the generated rules.

## Using the font: a class or a variable

The object `Geist()` returns has two ways in. `geistSans.className` is a class that sets the font directly. `geistSans.variable` is a class that only defines a CSS variable, `--font-geist-sans`, so CSS can use it anywhere below. create-next-app puts the `variable` classes on `html`, and points Tailwind at them in `app/globals.css`:

```css
@theme inline {
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
}
```

`@theme` defines Tailwind's design tokens, and `inline` makes the generated utility use the variable directly, so `font-sans` becomes `font-family: var(--font-geist-sans)`. One catch in the starter, which the lesson that created the project pointed out: its `globals.css` also sets `font-family: Arial, Helvetica, sans-serif` on `body`, so the page shows Arial until something uses `font-sans`. Delete that line and add `font-sans` to the `body` element's classes.

## Your own font files

For a font you have as a file, use `next/font/local`:

```tsx sketch
import localFont from "next/font/local";

const display = localFont({
  src: "./fonts/Trailhead-Display.woff2",
  variable: "--font-display",
});
```

The path is relative to the file that calls it. It gets the same treatment: hashed names, preloading, and an adjusted fallback. Each call to a font function adds one copy of that font to your site, so call it once, in `app/layout.tsx` or a small `fonts.ts`, and import the result wherever you need it.

